func parseAnyInt64(raw interface{}) int64 {
	raw = unwrapAvroUnion(raw)
	switch v := raw.(type) {
	case int64:
		return v
	case int:
		return int64(v)
	case int32:
		return int64(v)
	case float64:
		return int64(v)
	case json.Number:
		n, _ := v.Int64()
		return n
	case string:
		n, err := strconv.ParseInt(v, 10, 64)
		if err != nil {
			return 0
		}
		return n
	}
	return 0
}

func extractSourceTsMs(source interface{}) int64 {
	source = unwrapAvroUnion(source)
	m, ok := source.(map[string]interface{})
	if !ok {
		return 0
	}
	tsMs := parseAnyInt64(m["ts_ms"])
	if tsMs > 0 && tsMs%1000 == 0 {
		if ord := parseAnyInt64(m["ord"]); ord > 0 {
			if ord > 999 {
				ord = 999
			}
			tsMs += ord
		}
	}
	return tsMs
}

